BEGIN TRANSACTION;
CREATE TABLE bird_track_metrics (
	id INTEGER NOT NULL, 
	chunk_metric_id INTEGER NOT NULL, 
	track_id INTEGER NOT NULL, 
	bird_label VARCHAR(64) NOT NULL, 
	bird_type VARCHAR(32) NOT NULL, 
	feeding_s FLOAT, 
	feeding_bouts INTEGER, 
	reduced_eating_flag INTEGER, 
	drinking_s FLOAT, 
	drinking_bouts INTEGER, 
	inactivity_s FLOAT, 
	is_lethargic INTEGER, 
	pecking_aggressor_count INTEGER, 
	pecking_victim_count INTEGER, 
	avg_velocity_px_s FLOAT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(chunk_metric_id) REFERENCES half_hour_metrics (id)
);
CREATE TABLE half_hour_metrics (
	id INTEGER NOT NULL, 
	job_id INTEGER NOT NULL, 
	date_slot VARCHAR(32) NOT NULL, 
	hour_slot VARCHAR(32) NOT NULL, 
	chunk_index INTEGER NOT NULL, 
	chunk_start DATETIME NOT NULL, 
	chunk_end DATETIME NOT NULL, 
	temp_avg_c FLOAT NOT NULL, 
	temp_min_c FLOAT NOT NULL, 
	temp_max_c FLOAT NOT NULL, 
	humidity_avg_pct FLOAT NOT NULL, 
	humidity_min_pct FLOAT NOT NULL, 
	humidity_max_pct FLOAT NOT NULL, 
	ammonia_ppm_avg FLOAT NOT NULL, 
	ammonia_ppm_max FLOAT NOT NULL, 
	lux_avg FLOAT NOT NULL, 
	thi_avg FLOAT NOT NULL, 
	heat_stress_level VARCHAR(32) NOT NULL, 
	unique_birds_tracked INTEGER NOT NULL, 
	avg_birds_in_frame FLOAT NOT NULL, 
	flock_mobility_px_s FLOAT NOT NULL, 
	feeding_time_total_s FLOAT NOT NULL, 
	feeding_bouts INTEGER NOT NULL, 
	reduced_eating_events INTEGER NOT NULL, 
	reduced_eating_index FLOAT NOT NULL, 
	drinking_time_total_s FLOAT NOT NULL, 
	drinking_bouts INTEGER NOT NULL, 
	drinking_frequency_per_bird FLOAT NOT NULL, 
	inactivity_time_total_s FLOAT NOT NULL, 
	inactivity_pct FLOAT NOT NULL, 
	lethargic_birds_flagged INTEGER NOT NULL, 
	feather_pecking_events INTEGER NOT NULL, 
	agitation_score FLOAT NOT NULL, 
	created_at DATETIME, sensor_data_available BOOLEAN NOT NULL DEFAULT 0, 
	PRIMARY KEY (id), 
	FOREIGN KEY(job_id) REFERENCES processing_jobs (id)
);
CREATE TABLE processing_jobs (
	id INTEGER NOT NULL, 
	video_filename VARCHAR(255) NOT NULL, 
	video_path VARCHAR(512) NOT NULL, 
	date_slot VARCHAR(32) NOT NULL, 
	hour_slot VARCHAR(32) NOT NULL, 
	start_time DATETIME NOT NULL, 
	end_time DATETIME NOT NULL, 
	status VARCHAR(10) NOT NULL, 
	frames_processed INTEGER, 
	total_frames INTEGER, 
	processing_time_s FLOAT, 
	error_message TEXT, 
	created_at DATETIME, 
	completed_at DATETIME, progress_frames INTEGER, source_size BIGINT, source_mtime_ns BIGINT, source_ctime_ns BIGINT, 
	PRIMARY KEY (id)
);
CREATE INDEX ix_processing_jobs_date_slot ON processing_jobs (date_slot);
CREATE INDEX ix_processing_jobs_status ON processing_jobs (status);
CREATE UNIQUE INDEX ix_processing_jobs_video_filename ON processing_jobs (video_filename);
CREATE INDEX ix_processing_jobs_hour_slot ON processing_jobs (hour_slot);
CREATE INDEX ix_half_hour_metrics_chunk_end ON half_hour_metrics (chunk_end);
CREATE INDEX ix_half_hour_metrics_date_slot ON half_hour_metrics (date_slot);
CREATE INDEX idx_half_hour_date_hour ON half_hour_metrics (date_slot, hour_slot);
CREATE INDEX idx_half_hour_range ON half_hour_metrics (chunk_start, chunk_end);
CREATE INDEX ix_half_hour_metrics_job_id ON half_hour_metrics (job_id);
CREATE INDEX ix_half_hour_metrics_hour_slot ON half_hour_metrics (hour_slot);
CREATE INDEX ix_half_hour_metrics_chunk_start ON half_hour_metrics (chunk_start);
CREATE INDEX ix_bird_track_metrics_track_id ON bird_track_metrics (track_id);
CREATE INDEX ix_bird_track_metrics_chunk_metric_id ON bird_track_metrics (chunk_metric_id);
COMMIT;
